import{_ as t,o,c as i,ae as n}from"./chunks/framework.BjZAHlXD.js";const l="/300mind.documentation/assets/image_1.BenRTrr9.png",s="/300mind.documentation/assets/image_2.DEI_Xx5H.png",a="/300mind.documentation/assets/image_3.Bf6wYnkW.png",r="/300mind.documentation/assets/image_4.nGPNnPs8.png",p="/300mind.documentation/assets/image_5.C7TZOFCs.png",m="/300mind.documentation/assets/image_6.D69Fm8Tc.png",c="/300mind.documentation/assets/image_7.DezNZ8yk.png",u="/300mind.documentation/assets/image_8.DAbMUnnp.png",d="data:image/png;base64,",g="/300mind.documentation/assets/image_10.CWdTEGLz.png",h="/300mind.documentation/assets/image_11.B_or9JF-.png",b="/300mind.documentation/assets/image_12.CbXxZKND.png",f="/300mind.documentation/assets/image_13.Cxm7CfOW.png",A="/300mind.documentation/assets/image_14.C9bchKK9.png",P="/300mind.documentation/assets/image_15.BHD33lQP.png",w="/300mind.documentation/assets/image_16.BVS55ebq.png",C="/300mind.documentation/assets/image_17.B7GUULdw.png",v="/300mind.documentation/assets/image_18.C5LESgA-.png",S="data:image/png;base64,",T="data:image/png;base64,",H=JSON.parse('{"title":"Runtime Gizmo Tool","description":"","frontmatter":{},"headers":[],"relativePath":"unreal/runtime-gizmo-tool/index.md","filePath":"unreal/runtime-gizmo-tool/index.md"}'),y={name:"unreal/runtime-gizmo-tool/index.md"};function x(R,e,I,k,D,z){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="runtime-gizmo-tool" tabindex="-1"><strong>Runtime Gizmo Tool</strong> <a class="header-anchor" href="#runtime-gizmo-tool" aria-label="Permalink to &quot;**Runtime Gizmo Tool**&quot;">​</a></h1><h2 id="_1-introduction" tabindex="-1"><strong>1. Introduction</strong> <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;**1\\. Introduction**&quot;">​</a></h2><p>The Runtime Gizmo plugin provides an in-game transformation tool for Unreal Engine that allows users to move, rotate, and scale actors/components at runtime.</p><p>It enables editor-style manipulation inside gameplay, making it ideal for transforming objects at runtime.</p><p>The system supports:</p><ul><li><p>Translation (Move) , Rotation , Scaling of objects in level</p></li><li><p>Axis-based manipulation</p></li><li><p>World and Local space switching</p></li><li><p>Multi selection and cloning</p></li><li><p>Value based snapping</p></li><li><p>Blueprint integration</p></li></ul><h2 id="_2-installation" tabindex="-1"><strong>2. Installation</strong> <a class="header-anchor" href="#_2-installation" aria-label="Permalink to &quot;**2\\. Installation**&quot;">​</a></h2><ol><li><p>Add the plugin to your project (Engine or Project Plugins folder).</p></li><li><p>Open <strong>Edit → Plugins</strong>.</p></li><li><p>Enable <strong>Runtime Gizmo</strong>.</p></li><li><p>Restart the editor.<img src="'+l+'" alt=""></p></li></ol><h2 id="_3-required-setup" tabindex="-1"><strong>3. Required setup</strong> <a class="header-anchor" href="#_3-required-setup" aria-label="Permalink to &quot;**3\\. Required setup**&quot;">​</a></h2><h2 id="_3-1-component" tabindex="-1"><strong>3.1 Component</strong> <a class="header-anchor" href="#_3-1-component" aria-label="Permalink to &quot;**3.1 Component**&quot;">​</a></h2><p>To use the Runtime Gizmo system, you must add the:</p><p><strong>Runtime Gizmo Component</strong> to your <strong>Player Pawn</strong> (or Player Controller).</p><p><img src="'+s+'" alt=""><img src="'+a+'" alt=""></p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-4" tabindex="-1"><a class="header-anchor" href="#-4" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-5" tabindex="-1"><a class="header-anchor" href="#-5" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-6" tabindex="-1"><a class="header-anchor" href="#-6" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-7" tabindex="-1"><a class="header-anchor" href="#-7" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_3-2-implementation" tabindex="-1"><strong>3.2 Implementation</strong> <a class="header-anchor" href="#_3-2-implementation" aria-label="Permalink to &quot;**3.2 Implementation**&quot;">​</a></h2><h4 id="functions-to-implement" tabindex="-1">Functions to implement <a class="header-anchor" href="#functions-to-implement" aria-label="Permalink to &quot;Functions to implement&quot;">​</a></h4><p>To use the Runtime Gizmo, the following functions must be implemented:</p><ul><li><ul><li>Show and use gizmo <ul><li><p>Show Gizmo and Start Transform Process – Begins the transformation operation when interaction starts (e.g mouse press)</p></li><li><p>Stop Transform Process – Ends the transformation operation when interaction stops (e.g mouse release).</p></li></ul></li></ul></li></ul><p><img src="'+r+'" alt=""></p><ul><li><ul><li>Cloning <ul><li><p>To start cloning, set <strong>bIsCloning</strong> in the Runtime Gizmo Component to <strong>true</strong>.</p></li><li><p>To stop the cloning process, set <strong>bIsCloning</strong> to <strong>false</strong>.</p></li></ul></li></ul></li></ul><p><img src="'+p+'" alt=""></p><ul><li><ul><li>Multi Selection <ul><li><p>To enable multi-selection, set <strong>bIsSelectingMultipleObjects</strong> in the Runtime Gizmo Component to <strong>true</strong>.</p></li><li><p>To disable multi-selection, set <strong>bIsSelectingMultipleObjects</strong> to <strong>false</strong>.</p></li></ul></li></ul></li></ul><p><img src="'+m+'" alt=""></p><ul><li><ul><li>Delete selected objects <ul><li>To delete selected objects call <strong>DeselectAll(Destroy Selected = true)</strong> to destroy all the selected objects, If <strong>Destroy Selected</strong> is set to <strong>false</strong>, the actors will only be deselected and not destroyed.</li></ul></li></ul></li></ul><p><img src="'+c+'" alt=""></p><ul><li><ul><li>Snap Selected objects to ground <ul><li>To snap selected objects to the ground call <strong>Snap Selected Objects to Ground</strong></li></ul></li></ul></li></ul><p><strong><img src="'+u+'" alt=""></strong></p><h4 id="functions-to-override" tabindex="-1">Functions to override <a class="header-anchor" href="#functions-to-override" aria-label="Permalink to &quot;Functions to override&quot;">​</a></h4><ul><li><ul><li><strong>Should Select Object (Optional)</strong> : Used to determine whether a specific Actor or Component is eligible for selection and Gizmo interaction. <ul><li><p>This function allows you to:</p><ul><li><p>Control which objects can receive the Gizmo</p></li><li><p>Exclude specific actors or components from being selectable</p></li><li><p>Implement custom filtering logic (by class, tag, interface, etc.)</p></li></ul></li><li><p>Return value behavior:</p><ul><li><p>Return <strong>True</strong> – The object is allowed to be selected and can use the Gizmo.</p></li><li><p>Return <strong>False</strong> – The object is excluded from selection and will not receive the Gizmo.</p></li></ul></li></ul></li></ul></li></ul><p>Override this function to implement custom selection rules for your project.</p><p><img src="'+d+'" alt=""></p><p><strong><img src="'+g+'" alt=""></strong></p><ul><li><ul><li><strong>On Selection Change (Optional – Implement inside Runtime Gizmo Component) :</strong> Called automatically whenever a component or actor gains or loses selection focus. <ul><li>Parameters: <ul><li><p>Component – The affected component.</p><ul><li><p>If selection is Actor-based, this will be the actor’s Root Component.</p></li><li><p>If selection is Component-based, this will be the selected component itself.</p></li></ul></li><li><p>Is Component Based</p><ul><li><p>True → Selection is component-based.</p></li><li><p>False → Selection is actor-based.</p></li></ul></li><li><p>Selected – Indicates the current selection state.</p><ul><li><p>True → The object has gained focus (selected).</p></li><li><p>False → The object has lost focus (deselected).</p></li></ul></li></ul></li></ul></li></ul></li></ul><p><img src="'+h+'" alt=""></p><p>This event can be overridden to implement custom focus behavior such as:</p><ol><li><p>Highlight effects</p></li><li><p>UI updates</p></li><li><p>Outline toggling</p></li><li><p>Sound feedback</p><ul><li>It is especially useful for actors or components that do not implement the <strong>GizmoFocus</strong> interface.</li></ul></li></ol><h4 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h4><ul><li><ul><li><p><strong>Gizmo Focus Interface :</strong> The Gizmo Focus interface is used to define custom per-actor behavior when an actor or its component gains or loses selection focus(This interface is automatically triggered by the Runtime Gizmo Component.).</p><ul><li>It allows you to implement custom logic such as: <ul><li><p>Highlight effects</p></li><li><p>Material changes</p></li><li><p>UI updates</p></li><li><p>Sound feedback</p></li><li><p>Custom visual indicators</p></li></ul></li></ul></li><li><p>Whenever an actor or component receives or loses focus, the corresponding interface function is called automatically.</p></li><li><p>Use this interface when you want actors to handle their own focus behavior instead of relying on the OnSelectionChange event.<img src="'+b+'" alt=""><img src="'+f+'" alt=""></p></li></ul></li></ul><h2 id="_4-demo-content" tabindex="-1"><strong>4. Demo content</strong> <a class="header-anchor" href="#_4-demo-content" aria-label="Permalink to &quot;**4\\. Demo content**&quot;">​</a></h2><p>The plugin includes a complete working example located in:</p><p><strong>Plugins → Runtime Gizmo Content → RuntimeGizmo → Demo</strong> (Enable <strong>Show Plugin Content</strong> if not visible)</p><p>The Demo contains:</p><ul><li><p>A fully configured <strong>Player Pawn</strong> with all required input bindings</p></li><li><p>Actor containing description of all the available functions</p></li><li><p>A ready-to-use <strong>UI</strong> for mode switching and snapping</p></li><li><p>Transform mode switching (Move / Rotate / Scale)</p></li><li><p>World / Local space switching</p></li><li><p>Value based snapping controls</p></li><li><p>Cloning and Multi Selection</p></li></ul><p>Note : The Runtime Gizmo does <strong>not automatically handle input</strong>. You must use the included Demo Player Pawn or implement similar logic in your own Pawn or Player Controller.</p><p>For complete description of all Runtime Gizmo functions, refer to the BP_InfoActor located at: <strong>Plugins → Runtime Gizmo Content → RuntimeGizmo → Demo → BP_InfoActor</strong><img src="'+A+'" alt=""><img src="'+P+'" alt=""></p><h2 id="_5-runtime-gizmo-component-overview" tabindex="-1"><strong>5. Runtime Gizmo Component Overview</strong> <a class="header-anchor" href="#_5-runtime-gizmo-component-overview" aria-label="Permalink to &quot;**5\\. Runtime Gizmo Component Overview**&quot;">​</a></h2><h4 id="properties" tabindex="-1"><strong>Properties</strong> <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;**Properties**&quot;">​</a></h4><ul><li><ul><li><strong>Current Transform Space Type :</strong> Determines the coordinate space used by the Gizmo for transformations (Can also be modified at runtime). <ul><li>This defines whether the Gizmo operates in:</li></ul></li></ul></li><li><p>World Space – Transformations are aligned with the world axis.</p></li><li><p>Local Space – Transformations follow the selected actor’s local axis.</p></li></ul><p><strong><img src="'+w+'" alt=""></strong></p><ul><li><ul><li><strong>Gizmo Placement :</strong> Determines how the Gizmo is positioned when multiple actors are selected. <ul><li><p><strong>On First Selection</strong> – The Gizmo appears at the location of the first selected actor/component.</p></li><li><p><strong>On Last Selection</strong> – The Gizmo appears at the location of the most recently selected actor/component.</p></li></ul></li></ul></li></ul><p>**<img src="'+C+'" alt=""> **</p><ul><li><ul><li><p><strong>Current Gizmo Transformation</strong> : Defines the active transformation mode used by the Runtime Gizmo Component (Can also be modified at runtime).</p><ul><li><p><strong>None</strong> – Selection mode only. Allows selecting objects without applying any transformation.</p></li><li><p><strong>Location</strong> – Enables movement (translation) of selected objects.</p></li><li><p><strong>Rotation</strong> – Enables rotation of selected objects.</p></li><li><p><strong>Scale</strong> – Enables scaling of selected objects. <img src="'+v+'" alt=""></p></li></ul></li><li><p><strong>Force Component Mobility</strong> – Determines whether the Gizmo should override component mobility settings.</p><ul><li><strong>True</strong> – Components that are not set to Movable will automatically have their mobility changed to Movable to allow transformation.</li></ul></li></ul></li></ul><p>Warning : The original mobility setting is not restored after transformation.</p><ul><li><ul><li><ul><li><strong>False</strong> – No transformation will be applied to components that are set to Static or Stationary.</li></ul></li></ul></li></ul><p><img src="'+S+'" alt=""></p><ul><li><ul><li><strong>Toggle Selected in Multi Selection</strong> – Determines whether clicking an already selected object will deselect it or not in multi select. <ul><li><p><strong>Enabled (True)</strong> – Clicking a selected actor will remove it from the current selection set.</p></li><li><p><strong>Disabled (False)</strong> – Clicking a selected actor will keep it selected.</p></li></ul></li></ul></li></ul><p><img src="'+T+'" alt=""></p><h4 id="functions" tabindex="-1"><strong>Functions</strong> <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;**Functions**&quot;">​</a></h4><p>The Runtime Gizmo Component exposes multiple Blueprint callable functions for selection, transformation, snapping, cloning, and multi-selection management.</p><p>For a complete and detailed explanation of all available functions, refer to the <strong>BP_InfoActor</strong> located at:</p><p><strong>Plugins → Runtime Gizmo → Content → RuntimeGizmo → Demo → BP_InfoActor</strong></p><p>(Enable <strong>Show Plugin Content</strong> if not visible.)</p>',69)])])}const q=t(y,[["render",x]]);export{H as __pageData,q as default};
